WITH enriched AS (SELECT id, customer_id, order_date, status, channel, amount, discount, FIRST_VALUE(amount, TRUE) OVER w_recent AS first_known_amount, CORR(amount, discount) OVER (PARTITION BY status) AS corr_amount_discount, ROW_NUMBER() OVER (ORDER BY order_date DESC, id) AS event_seq FROM orders WINDOW w_recent AS (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN first_known_amount >= 1550 THEN 'PREMIUM' ELSE 'STANDARD' END AS first_known_amount_tier, CASE WHEN discount >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, PERCENTILE_APPROX(corr_amount_discount, ARRAY(0.25, 0.5, 0.75)) AS corr_amount_discount_quartiles, COUNT(DISTINCT status) AS distinct_status, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows, SIZE(COLLECT_SET(channel)) AS num_channels, COUNT(*) AS row_count, GROUPING(CASE WHEN first_known_amount >= 1550 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM enriched GROUP BY ROLLUP (CASE WHEN first_known_amount >= 1550 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN discount >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END);
